package com.loopers.application.event;import com.loopers.domain.event.*;import com.loopers.infrastructure.event.OutboxJpaRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
// Hides: single-row relay locking, publish-before-status ordering, and crash seam.
@Component @RequiredArgsConstructor public class OutboxRelay{private final OutboxJpaRepository repo;private final OutboxPublisher publisher;@Transactional public void relay(long id,boolean crashAfterAck){OutboxEvent e=repo.findLocked(id).orElseThrow();if(e.getStatus()==OutboxEvent.Status.PUBLISHED)return;publisher.publish(e.getEventId(),e.getPayload());if(crashAfterAck)throw new CrashAfterPublish();e.published();}public static class CrashAfterPublish extends RuntimeException{}}
